insert into posts (id, author_id, type, topic, title, text, images, recipe, steps, tags, likes_count, created_at) values
  ('00000000-0000-4000-9000-000000000001', '00000000-0000-4000-8000-000000000001', 'recipe', 'breakfast', 'Сырники, которые не разваливаются', 'Секрет — отжатый творог и минимум муки. Получаются пышные, с хрустящей корочкой. Проверено на трёх поколениях семьи.', '[{"seed":101,"tag":"cheesecake,pancakes","ratio":1.25}]'::jsonb, '{"time":"25 мин","servings":3,"difficulty":"Легко","ingredients":["Творог 9% — 400 г","Яйцо — 1 шт.","Сахар — 2 ст. л.","Мука — 3 ст. л. + для обваливания","Ванильный сахар — щепотка","Масло для жарки"],"steps":["Творог отожмите через марлю и протрите через сито — так сырники будут нежными.","Смешайте творог с яйцом, сахаром и ванилью. Добавьте муку и быстро перемешайте.","Влажными руками сформируйте шайбы толщиной 1,5 см, обваляйте в муке.","Жарьте на среднем огне по 3 минуты с каждой стороны под крышкой."]}'::jsonb, null, array['завтрак', 'творог', 'быстро']::text[], 1240, now() - interval '180 minutes'),
  ('00000000-0000-4000-9000-000000000002', '00000000-0000-4000-8000-000000000008', 'hack', 'cleaning', 'Как отмыть противень за 10 минут', 'Без химии и железной губки. Нужны сода, перекись и фольга.', '[{"seed":102,"tag":"baking,tray","ratio":1.4}]'::jsonb, null, '[{"text":"Посыпьте противень толстым слоем соды."},{"text":"Сбрызните перекисью водорода, чтобы сода стала влажной кашицей.","img":{"seed":1021,"tag":"cleaning","ratio":0.75}},{"text":"Подождите 10 минут и пройдитесь по нагару скомканной фольгой."},{"text":"Смойте тёплой водой."}]'::jsonb, array['уборка', 'кухня', 'сода']::text[], 3820, now() - interval '300 minutes'),
  ('00000000-0000-4000-9000-000000000003', '00000000-0000-4000-8000-000000000002', 'beforeafter', 'repair', 'Покрасил старый кухонный гарнитур', 'Фасады из 90-х: шкурка, грунт и два слоя краски для мебели. Ушло два выходных и 6 тысяч рублей.', '[{"seed":103,"tag":"kitchen,old","ratio":1.2},{"seed":1031,"tag":"kitchen,modern","ratio":1.2}]'::jsonb, null, null, array['ремонт', 'кухня', 'покраска']::text[], 2150, now() - interval '480 minutes'),
  ('00000000-0000-4000-9000-000000000004', '00000000-0000-4000-8000-000000000003', 'photo', 'knitting', 'Плед из толстой пряжи руками', 'Без спиц и крючка, за один вечер. Ушло 6 мотков пряжи.', '[{"seed":104,"tag":"knitting,blanket","ratio":1.5}]'::jsonb, null, null, array['вязание', 'плед', 'уют']::text[], 980, now() - interval '600 minutes'),
  ('00000000-0000-4000-9000-000000000005', '00000000-0000-4000-8000-000000000004', 'hack', 'garden', 'Рассада в яичной скорлупе', 'Скорлупа — готовый горшок и подкормка. Сажаете в грунт прямо с ней, слегка надавив.', '[{"seed":105,"tag":"seedlings","ratio":1.1}]'::jsonb, null, '[{"text":"Сделайте иглой отверстие в дне скорлупы для стока воды."},{"text":"Насыпьте грунт и посейте 1–2 семечка."},{"text":"Поставьте скорлупки в коробку из-под яиц на светлый подоконник."}]'::jsonb, array['рассада', 'дача', 'бесплатно']::text[], 760, now() - interval '840 minutes'),
  ('00000000-0000-4000-9000-000000000006', '00000000-0000-4000-8000-000000000007', 'recipe', 'baking', 'Хлеб без замеса за 5 минут работы', 'Тесто стоит ночь в холодильнике, утром — в духовку. Хрустящая корка как из пекарни.', '[{"seed":106,"tag":"bread,loaf","ratio":1}]'::jsonb, '{"time":"14 ч (активно 5 мин)","servings":6,"difficulty":"Легко","ingredients":["Мука — 450 г","Вода тёплая — 350 мл","Соль — 1,5 ч. л.","Сухие дрожжи — ½ ч. л."],"steps":["Смешайте всё ложкой до однородного липкого теста, накройте плёнкой.","Оставьте на 12–14 часов при комнатной температуре или в холодильнике.","Разогрейте духовку до 240 °C вместе с чугунной кастрюлей.","Выложите тесто в кастрюлю, выпекайте 30 мин под крышкой и 15 мин без неё."]}'::jsonb, null, array['хлеб', 'выпечка']::text[], 1890, now() - interval '1080 minutes'),
  ('00000000-0000-4000-9000-000000000007', '00000000-0000-4000-8000-000000000005', 'photo', 'storage', 'Хранение в прихожей 4 м²', 'Полка для обуви под банкеткой, крючки в два уровня и корзины наверху. Всё влезло.', '[{"seed":107,"tag":"hallway,interior","ratio":1.45}]'::jsonb, null, null, array['хранение', 'прихожая', 'маленькая квартира']::text[], 4410, now() - interval '1200 minutes'),
  ('00000000-0000-4000-9000-000000000008', '00000000-0000-4000-8000-000000000006', 'recipe', 'grill', 'Плов в казане на костре', 'Классика по-узбекски: курдючный жир, морковь соломкой и рис девзира.', '[{"seed":108,"tag":"pilaf,rice","ratio":0.9}]'::jsonb, '{"time":"2 ч","servings":8,"difficulty":"Средне","ingredients":["Баранина — 1 кг","Рис — 1 кг","Морковь — 1 кг","Лук — 3 шт.","Масло — 200 мл","Чеснок — 2 головки","Зира, барбарис, соль"],"steps":["Раскалите масло, обжарьте лук до золотистого цвета.","Добавьте мясо, обжарьте до корочки, затем морковь соломкой.","Залейте водой, добавьте специи, тушите 40 минут — это зирвак.","Выложите промытый рис ровным слоем, залейте водой на 1,5 см выше.","Когда вода уйдёт, воткните чеснок, накройте и томите 25 минут."]}'::jsonb, null, array['казан', 'пикник', 'мясо']::text[], 1320, now() - interval '1560 minutes'),
  ('00000000-0000-4000-9000-000000000009', '00000000-0000-4000-8000-000000000008', 'hack', 'hacks', 'Чистим зелень за 30 секунд', 'Петрушку и укроп удобно обрывать через тёрку — стебли остаются, листья падают в миску.', '[{"seed":109,"tag":"parsley,herbs","ratio":1.2}]'::jsonb, null, '[{"text":"Проденьте стебель в самое крупное отверстие тёрки изнутри."},{"text":"Протяните — листья останутся по ту сторону."}]'::jsonb, array['кухня', 'зелень']::text[], 5120, now() - interval '1800 minutes'),
  ('00000000-0000-4000-9000-000000000010', '00000000-0000-4000-8000-000000000003', 'photo', 'decor', 'Свечи в старых чашках', 'Соевый воск, хлопковый фитиль и пара капель эфирного масла. Отличный подарок.', '[{"seed":110,"tag":"candle,handmade","ratio":1.35}]'::jsonb, null, null, array['свечи', 'подарок', 'своими руками']::text[], 1630, now() - interval '2040 minutes'),
  ('00000000-0000-4000-9000-000000000011', '00000000-0000-4000-8000-000000000004', 'beforeafter', 'garden', 'Заросший участок → грядки', 'Высокие грядки из досок, дорожки из щепы. Первый урожай уже в июле.', '[{"seed":111,"tag":"overgrown,garden","ratio":1},{"seed":1111,"tag":"vegetable,garden","ratio":1}]'::jsonb, null, null, array['дача', 'грядки']::text[], 890, now() - interval '2400 minutes'),
  ('00000000-0000-4000-9000-000000000012', '00000000-0000-4000-8000-000000000007', 'recipe', 'baking', 'Шарлотка без сахара', 'Сладость даёт банан и яблоки. Детям нравится.', '[{"seed":112,"tag":"apple,pie","ratio":1.15}]'::jsonb, '{"time":"50 мин","servings":6,"difficulty":"Легко","ingredients":["Яйца — 3 шт.","Спелый банан — 1 шт.","Мука — 150 г","Яблоки — 4 шт.","Корица — ½ ч. л."],"steps":["Взбейте яйца с бананом в пышную массу.","Вмешайте муку и корицу.","Выложите яблоки дольками в форму, залейте тестом.","Выпекайте 35–40 минут при 180 °C."]}'::jsonb, null, array['выпечка', 'без сахара', 'яблоки']::text[], 2240, now() - interval '2640 minutes'),
  ('00000000-0000-4000-9000-000000000013', '00000000-0000-4000-8000-000000000005', 'photo', 'interior', 'Рабочее место на балконе', 'Утеплили, поставили узкий стол вдоль окна — теперь это лучший кабинет в квартире.', '[{"seed":113,"tag":"balcony,desk","ratio":1.3}]'::jsonb, null, null, array['балкон', 'кабинет']::text[], 2670, now() - interval '3000 minutes'),
  ('00000000-0000-4000-9000-000000000014', '00000000-0000-4000-8000-000000000002', 'hack', 'repair', 'Не скрипят двери — смажьте мылом', 'Если нет масла, сухое хозяйственное мыло отлично работает на петлях.', '[{"seed":114,"tag":"door,hinge","ratio":1.5}]'::jsonb, null, '[{"text":"Приподнимите дверь отвёрткой и снимите с петель."},{"text":"Натрите штырь петли сухим мылом."},{"text":"Поставьте дверь обратно и поработайте ею."}]'::jsonb, array['ремонт', 'мелочи']::text[], 1410, now() - interval '3360 minutes'),
  ('00000000-0000-4000-9000-000000000015', '00000000-0000-4000-8000-000000000001', 'recipe', 'recipes', 'Борщ, который любят все', 'Свёклу тушим отдельно с уксусом — цвет остаётся ярко-рубиновым.', '[{"seed":115,"tag":"borscht,soup","ratio":1}]'::jsonb, '{"time":"2 ч 30 мин","servings":8,"difficulty":"Средне","ingredients":["Говядина на кости — 800 г","Свёкла — 2 шт.","Капуста — 400 г","Картофель — 4 шт.","Морковь, лук — по 1 шт.","Томатная паста — 2 ст. л.","Уксус 9% — 1 ч. л."],"steps":["Сварите бульон, 1,5 часа на слабом огне.","Свёклу натрите и потушите с уксусом и пастой 15 минут.","Обжарьте лук и морковь.","В бульон: картофель, через 10 минут — капусту, затем зажарку и свёклу.","Дайте настояться 30 минут под крышкой."]}'::jsonb, null, array['суп', 'обед', 'классика']::text[], 1780, now() - interval '3720 minutes'),
  ('00000000-0000-4000-9000-000000000016', '00000000-0000-4000-8000-000000000004', 'photo', 'garden', 'Огурцы на шпалере в теплице', 'Подвязываю к сетке — места в два раза больше, огурцы чистые.', '[{"seed":116,"tag":"cucumber,greenhouse","ratio":1.4}]'::jsonb, null, null, array['теплица', 'огурцы']::text[], 640, now() - interval '4200 minutes'),
  ('00000000-0000-4000-9000-000000000017', '00000000-0000-4000-8000-000000000003', 'hack', 'crafts', 'Нитки не путаются: банка с дыркой', 'Клубок в банку, нитка через отверстие в крышке — котик не достанет, клубок не укатится.', '[{"seed":117,"tag":"yarn,jar","ratio":1.25}]'::jsonb, null, '[{"text":"Проделайте в крышке банки отверстие и зашкурьте края."},{"text":"Положите клубок внутрь, выведите нитку наружу."}]'::jsonb, array['вязание', 'хранение']::text[], 1150, now() - interval '4560 minutes'),
  ('00000000-0000-4000-9000-000000000018', '00000000-0000-4000-8000-000000000005', 'beforeafter', 'storage', 'Шкаф после метода коробок', 'Одна полка — одна категория, всё вертикально. Утром собираться в два раза быстрее.', '[{"seed":118,"tag":"messy,closet","ratio":1.3},{"seed":1181,"tag":"wardrobe,organized","ratio":1.3}]'::jsonb, null, null, array['хранение', 'порядок']::text[], 3060, now() - interval '5040 minutes'),
  ('00000000-0000-4000-9000-000000000019', '00000000-0000-4000-8000-000000000006', 'recipe', 'grill', 'Шашлык из курицы в кефире', 'Маринад на 2 часа — и мясо получается сочным даже у новичка.', '[{"seed":119,"tag":"shashlik,grill","ratio":1.2}]'::jsonb, '{"time":"2 ч 40 мин","servings":4,"difficulty":"Легко","ingredients":["Бедро куриное — 1,5 кг","Кефир — 500 мл","Лук — 3 шт.","Соль, перец, паприка"],"steps":["Нарежьте мясо крупно, лук кольцами.","Залейте кефиром со специями, оставьте на 2 часа.","Жарьте на углях 20–25 минут, часто переворачивая."]}'::jsonb, null, array['мангал', 'курица']::text[], 990, now() - interval '5400 minutes'),
  ('00000000-0000-4000-9000-000000000020', '00000000-0000-4000-8000-000000000003', 'photo', 'crafts', 'Макраме-кашпо для зала', 'Схема из трёх узлов, справится любой. Хлопковый шнур 5 мм.', '[{"seed":120,"tag":"macrame,plant","ratio":1.6}]'::jsonb, null, null, array['макраме', 'растения']::text[], 720, now() - interval '6000 minutes'),
  ('00000000-0000-4000-9000-000000000021', '00000000-0000-4000-8000-000000000008', 'hack', 'hacks', 'Банан не темнеет: плёнка на хвостик', 'Оберните хвостики грозди пищевой плёнкой — бананы лежат на 3–4 дня дольше.', '[{"seed":121,"tag":"banana","ratio":1}]'::jsonb, null, '[{"text":"Отделите бананы от грозди."},{"text":"Плотно оберните каждый хвостик плёнкой."}]'::jsonb, array['кухня', 'хранение продуктов']::text[], 2890, now() - interval '6600 minutes'),
  ('00000000-0000-4000-9000-000000000022', '00000000-0000-4000-8000-000000000002', 'photo', 'diy', 'Полки из обрезков доски', 'Остались от ремонта пола. Масло с воском, скрытый крепёж.', '[{"seed":122,"tag":"wooden,shelf","ratio":1.35}]'::jsonb, null, null, array['дерево', 'своими руками']::text[], 1980, now() - interval '7200 minutes'),
  ('00000000-0000-4000-9000-000000000023', '00000000-0000-4000-8000-000000000007', 'recipe', 'baking', 'Овсяное печенье на завтрак', 'Три ингредиента, без муки и сахара. Можно взять с собой.', '[{"seed":123,"tag":"oatmeal,cookies","ratio":1.1}]'::jsonb, '{"time":"20 мин","servings":12,"difficulty":"Легко","ingredients":["Овсяные хлопья — 150 г","Бананы — 2 шт.","Изюм или орехи — 50 г"],"steps":["Разомните бананы вилкой и смешайте с хлопьями.","Добавьте изюм или орехи.","Выложите ложкой на пергамент, выпекайте 15 минут при 180 °C."]}'::jsonb, null, array['печенье', 'полезно', 'быстро']::text[], 1560, now() - interval '7800 minutes'),
  ('00000000-0000-4000-9000-000000000024', '00000000-0000-4000-8000-000000000004', 'photo', 'garden', 'Клумба, которая цветёт всё лето', 'Подобрал многолетники по срокам цветения: от тюльпанов до астр.', '[{"seed":124,"tag":"flowerbed","ratio":1.25}]'::jsonb, null, null, array['цветы', 'клумба']::text[], 830, now() - interval '8400 minutes'),
  ('00000000-0000-4000-9000-000000000025', '00000000-0000-4000-8000-000000000003', 'beforeafter', 'sewing', 'Перешила старый свитер в кардиган', 'Разрезала по центру, обработала края тесьмой, пришила пуговицы.', '[{"seed":125,"tag":"sweater","ratio":1.3},{"seed":1251,"tag":"cardigan","ratio":1.3}]'::jsonb, null, null, array['перешив', 'одежда']::text[], 1340, now() - interval '9000 minutes'),
  ('00000000-0000-4000-9000-000000000026', '00000000-0000-4000-8000-000000000005', 'hack', 'storage', 'Пакеты в коробке из-под салфеток', 'Больше никакого «пакета с пакетами». Достаётся по одному.', '[{"seed":126,"tag":"plastic,bags","ratio":1.2}]'::jsonb, null, '[{"text":"Сложите каждый пакет полоской и сверните."},{"text":"Уложите в коробку так, чтобы край следующего торчал."}]'::jsonb, array['хранение', 'кухня']::text[], 2210, now() - interval '9600 minutes'),
  ('00000000-0000-4000-9000-000000000027', '00000000-0000-4000-8000-000000000001', 'recipe', 'recipes', 'Ленивые голубцы в духовке', 'Все вкусы голубцов без заворачивания. Отлично разогреваются.', '[{"seed":127,"tag":"meatballs,cabbage","ratio":1}]'::jsonb, '{"time":"1 ч","servings":5,"difficulty":"Легко","ingredients":["Фарш — 500 г","Капуста — 300 г","Рис отварной — 150 г","Яйцо — 1 шт.","Сметана — 200 г","Томатная паста — 2 ст. л."],"steps":["Мелко нашинкуйте капусту, смешайте с фаршем, рисом и яйцом.","Сформируйте котлеты, уложите в форму.","Залейте соусом из сметаны, пасты и стакана воды.","Запекайте 40 минут при 190 °C."]}'::jsonb, null, array['ужин', 'фарш']::text[], 1120, now() - interval '10200 minutes'),
  ('00000000-0000-4000-9000-000000000028', '00000000-0000-4000-8000-000000000005', 'photo', 'kids', 'Детская на 9 метрах', 'Кровать-чердак освободила пол для игр. Цвета — тёплый беж и шалфей.', '[{"seed":128,"tag":"kids,room","ratio":1.4}]'::jsonb, null, null, array['детская', 'маленькая квартира']::text[], 3550, now() - interval '10800 minutes'),
  ('00000000-0000-4000-9000-000000000029', '00000000-0000-4000-8000-000000000004', 'hack', 'garden', 'Полив из бутылки на неделю', 'Уезжаете — растения не засохнут. Бутылка с проколотой крышкой горлышком в грунт.', '[{"seed":129,"tag":"watering,plant","ratio":1.3}]'::jsonb, null, '[{"text":"Проколите в крышке 3–4 отверстия."},{"text":"Наполните бутылку и воткните горлышком в землю у корня."}]'::jsonb, array['полив', 'дача', 'отпуск']::text[], 470, now() - interval '11400 minutes'),
  ('00000000-0000-4000-9000-000000000030', '00000000-0000-4000-8000-000000000006', 'photo', 'grill', 'Завтрак в походе', 'Яичница на чугунке и хлеб с костра. Самое вкусное утро.', '[{"seed":130,"tag":"camping,breakfast","ratio":0.85}]'::jsonb, null, null, array['поход', 'завтрак']::text[], 610, now() - interval '12000 minutes');
insert into tries (post_id, user_id, ok, text, img, created_at) values
  ('00000000-0000-4000-9000-000000000001', '00000000-0000-4000-8000-000000000005', true, 'Получились с первого раза! Добавила изюм.', '{"seed":201,"tag":"cheesecake","ratio":1}'::jsonb, now() - interval '120 minutes'),
  ('00000000-0000-4000-9000-000000000001', '00000000-0000-4000-8000-000000000002', true, 'Отжимал творог ночь — вообще не разваливались.', null, now() - interval '360 minutes'),
  ('00000000-0000-4000-9000-000000000001', '00000000-0000-4000-8000-000000000008', false, 'Взяла жидкий творог, растеклись. Сама виновата.', null, now() - interval '540 minutes'),
  ('00000000-0000-4000-9000-000000000001', '00000000-0000-4000-8000-000000000004', true, null, '{"seed":202,"tag":"pancakes","ratio":1}'::jsonb, now() - interval '1200 minutes'),
  ('00000000-0000-4000-9000-000000000001', '00000000-0000-4000-8000-000000000003', true, 'Жарила под крышкой — пышные!', null, now() - interval '1800 minutes'),
  ('00000000-0000-4000-9000-000000000002', '00000000-0000-4000-8000-000000000001', true, 'Работает! Противень как новый.', '{"seed":203,"tag":"clean,kitchen","ratio":1}'::jsonb, now() - interval '240 minutes'),
